import React from 'react';

const TICKERS = [
  { s: 'AAPL',  p: 214.35, c: +1.24 }, { s: 'MSFT',  p: 415.82, c: -0.87 },
  { s: 'NVDA',  p: 132.45, c: +3.21 }, { s: 'TSLA',  p: 185.20, c: -2.15 },
  { s: 'GOOGL', p: 192.78, c: +0.95 }, { s: 'META',  p: 718.40, c: +1.82 },
  { s: 'AMZN',  p: 228.15, c: +0.43 }, { s: 'JPM',   p: 265.90, c: -0.31 },
  { s: '^SPX',  p: 5890.24,c: +0.67 }, { s: '^VIX',  p: 18.45,  c: +0.89 },
];

const TickerTape = () => {
  const items = [...TICKERS, ...TICKERS]; // duplicate for seamless loop
  return (
    <div className="ticker-tape">
      <div className="ticker-scroll">
        {items.map((t, i) => (
          <span key={i} className="t-item">
            <span className="t-sym">{t.s}</span>
            <span className="t-px">${t.p.toLocaleString()}</span>
            <span className={t.c >= 0 ? 't-up' : 't-dn'}>
              {t.c >= 0 ? '▲' : '▼'}{Math.abs(t.c).toFixed(2)}%
            </span>
            <span className="t-sep">│</span>
          </span>
        ))}
      </div>
    </div>
  );
};

export default TickerTape;
